from pathlib import Path
p=Path('index.html')
s=p.read_text()
marker='/* Sudoku: full-screen contextual number palette */'
if marker in s:
    raise SystemExit('already patched')
css='''\n/* Sudoku: full-screen contextual number palette */\nbody:has(#sudokuPage.active) .topbar{display:none}\nbody:has(#sudokuPage.active) #app{min-height:100dvh}\n#sudokuPage{height:100dvh;min-height:0;max-width:none;padding:max(8px,env(safe-area-inset-top)) 12px max(8px,env(safe-area-inset-bottom));overflow:hidden;background:#fff radial-gradient(circle,#dce5f8 1px,transparent 1.35px);background-size:28px 28px}\n#sudokuPage.active{display:flex;flex-direction:column;gap:8px}\n#sudokuPage .game-heading{flex:0 0 auto;width:min(620px,100%);margin:0 auto;padding:2px 0 3px;grid-template-columns:44px minmax(0,1fr) auto;gap:11px}\n#sudokuPage .game-heading h1{font-size:25px;font-weight:550}\n#sudokuPage .eyebrow{margin:0 0 3px;font-size:9px;font-weight:600;color:#8d9ab8}\n#sudokuPage .back-button{border:0;box-shadow:none;background:#ffffffd9;color:#8495b7}\n#sudokuPage .heading-stat b{font-size:18px;color:#3568ee;font-weight:600}\n#sudokuPage .heading-stat span{font-size:9px}\n#sudokuPage .sudoku-toolbar{flex:0 0 auto;width:min(620px,100%);margin:0 auto 2px;display:flex;justify-content:center;gap:9px}\n#sudokuPage .sudoku-toolbar label{font-size:11px;background:#ffffffd9;border:1px solid #e4eaf7;border-radius:999px;padding:3px 4px 3px 10px}\n#sudokuPage .sudoku-toolbar select{border:0;background:transparent;padding:6px 24px 6px 5px;color:#53627e}\n#sudokuPage #newSudoku{border-radius:999px;padding:8px 13px;box-shadow:none;background:#ffffffd9}\n#sudokuPage .sudoku-board{flex:0 0 auto;width:min(620px,calc(100vw - 24px),calc(100dvh - 205px));max-width:100%;margin:2px auto 0;border:1.5px solid #8c99b2;border-radius:16px;box-shadow:none;background:#fff}\n#sudokuPage .sudoku-cell{font-size:clamp(18px,5.2vw,30px);background:#fffffff0;transition:background .12s ease,transform .08s ease}\n#sudokuPage .sudoku-cell.selected{background:#e9f0ff;box-shadow:inset 0 0 0 2px #7598ef}\n#sudokuPage .sudoku-cell.peer{background:#f7f9fe}\n#sudokuPage .sudoku-cell.same{background:#edf3ff;color:#3568ee}\n#sudokuPage .sudoku-tools{flex:0 0 auto;width:min(240px,100%);grid-template-columns:repeat(2,1fr);gap:8px;margin:4px auto 0}\n#sudokuPage .sudoku-tools .soft-button{height:42px;border-radius:999px;background:#ffffffde;box-shadow:none}\n#sudokuPage #sudokuMessage{flex:0 0 auto;margin:0 auto;min-height:18px;font-size:11px;color:#8997b2}\n#sudokuNumbers{position:fixed;z-index:120;display:none;width:194px;grid-template-columns:repeat(3,1fr);gap:7px;padding:10px;background:rgba(255,255,255,.97);border:1px solid #dfe7f7;border-radius:22px;box-shadow:0 18px 50px rgba(35,52,88,.18);backdrop-filter:blur(12px);margin:0}\n#sudokuNumbers.open{display:grid}\n#sudokuNumbers button{width:100%;height:50px;aspect-ratio:auto;border:0;border-radius:14px;background:#f5f8ff;color:#3568ee;font-size:21px;font-weight:650;box-shadow:none}\n#sudokuNumbers button:active{transform:scale(.95);background:#e9f0ff}\n#sudokuNumbers button:disabled{opacity:.22}\n#sudokuNumbers #sudokuPencil{grid-column:span 2;font-size:12px;color:#667796;background:#f7f9fd}\n#sudokuNumbers #sudokuPencil[aria-pressed="true"]{background:#3568ee;color:#fff}\n#sudokuNumbers #sudokuErase{font-size:16px;color:#667796;background:#f7f9fd}\n@media(max-height:700px) and (orientation:portrait){#sudokuPage{gap:4px}#sudokuPage .game-heading h1{font-size:22px}#sudokuPage .sudoku-toolbar{margin:0}#sudokuPage .sudoku-board{width:min(calc(100vw - 24px),calc(100dvh - 178px))}#sudokuPage .sudoku-tools .soft-button{height:36px}#sudokuPage #sudokuMessage{display:none}}\n'''
needle='\n/* Snake-only true full-screen playfield */'
if needle not in s:
    raise SystemExit('CSS insertion point not found')
s=s.replace(needle,css+needle,1)
old_select="""function selectSudoku(i,rerender=true){if(!sudoku)return;sudoku.selected=i;const r=Math.floor(i/9),c=i%9,val=sudoku.board[r][c];document.querySelectorAll('.sudoku-cell').forEach((el,j)=>{const rr=Math.floor(j/9),cc=j%9,same=val&&sudoku.board[rr][cc]===val;el.classList.toggle('selected',j===i);el.classList.toggle('peer',j!==i&&(rr===r||cc===c||(Math.floor(rr/3)===Math.floor(r/3)&&Math.floor(cc/3)===Math.floor(c/3))));el.classList.toggle('same',j!==i&&!!same);el.classList.toggle('error',!!sudoku.board[rr][cc]&&sudoku.board[rr][cc]!==sudoku.solution[rr][cc]&&!sudoku.puzzle[rr][cc])});if(rerender)saveSudoku()}"""
new_select="""function closeSudokuPad(){const pad=$('sudokuNumbers');if(pad)pad.classList.remove('open')}
function positionSudokuPad(i){const pad=$('sudokuNumbers'),cell=document.querySelector(`.sudoku-cell[data-i=\"${i}\"]`);if(!pad||!cell)return;const r=Math.floor(i/9),c=i%9;if(sudoku.solved||sudoku.puzzle[r][c]){closeSudokuPad();return}pad.classList.add('open');[...pad.querySelectorAll('button')].slice(0,9).forEach((b,n)=>{b.disabled=sudoku.board.flat().filter(v=>v===n+1).length>=9});requestAnimationFrame(()=>{const cr=cell.getBoundingClientRect(),w=pad.offsetWidth,h=pad.offsetHeight,margin=8;let left=cr.left+cr.width/2-w/2;left=Math.max(margin,Math.min(window.innerWidth-w-margin,left));let top=cr.bottom+8;if(top+h>window.innerHeight-margin)top=cr.top-h-8;top=Math.max(margin,Math.min(window.innerHeight-h-margin,top));pad.style.left=left+'px';pad.style.top=top+'px'})}
function selectSudoku(i,rerender=true){if(!sudoku)return;if(i==null){sudoku.selected=null;closeSudokuPad();return}sudoku.selected=i;const r=Math.floor(i/9),c=i%9,val=sudoku.board[r][c];document.querySelectorAll('.sudoku-cell').forEach((el,j)=>{const rr=Math.floor(j/9),cc=j%9,same=val&&sudoku.board[rr][cc]===val;el.classList.toggle('selected',j===i);el.classList.toggle('peer',j!==i&&(rr===r||cc===c||(Math.floor(rr/3)===Math.floor(r/3)&&Math.floor(cc/3)===Math.floor(c/3))));el.classList.toggle('same',j!==i&&!!same);el.classList.toggle('error',!!sudoku.board[rr][cc]&&sudoku.board[rr][cc]!==sudoku.solution[rr][cc]&&!sudoku.puzzle[rr][cc])});if(rerender){saveSudoku();positionSudokuPad(i)}}"""
if old_select not in s:
    raise SystemExit('selectSudoku source not found')
s=s.replace(old_select,new_select,1)
old_action="""function sudokuAction(num){const i=sudoku.selected;if(i==null)return;const r=Math.floor(i/9),c=i%9;if(sudoku.puzzle[r][c]||sudoku.solved)return;const prev=sudoku.board[r][c],prevNotes=[...(sudoku.notes[i]||[])];sudoku.history.push({i,prev,prevNotes});if(pencil&&num){if(prev)return sudoku.history.pop();const set=new Set(prevNotes);set.has(num)?set.delete(num):set.add(num);sudoku.notes[i]=[...set].sort();}else{sudoku.board[r][c]=num||0;sudoku.notes[i]=[]}checkSudoku();saveSudoku();renderSudoku();selectSudoku(i,false)}"""
new_action="""function sudokuAction(num){const i=sudoku.selected;if(i==null)return;const r=Math.floor(i/9),c=i%9;if(sudoku.puzzle[r][c]||sudoku.solved)return;const prev=sudoku.board[r][c],prevNotes=[...(sudoku.notes[i]||[])];sudoku.history.push({i,prev,prevNotes});if(pencil&&num){if(prev)return sudoku.history.pop();const set=new Set(prevNotes);set.has(num)?set.delete(num):set.add(num);sudoku.notes[i]=[...set].sort();}else{sudoku.board[r][c]=num||0;sudoku.notes[i]=[]}checkSudoku();saveSudoku();renderSudoku();selectSudoku(i,false);if(pencil&&num)positionSudokuPad(i);else closeSudokuPad()}"""
if old_action not in s:
    raise SystemExit('sudokuAction source not found')
s=s.replace(old_action,new_action,1)
old_pad="""for(let n=1;n<=9;n++){const b=document.createElement('button');b.textContent=n;b.addEventListener('click',()=>sudokuAction(n));$('sudokuNumbers').appendChild(b)}"""
new_pad="""for(let n=1;n<=9;n++){const b=document.createElement('button');b.textContent=n;b.setAttribute('aria-label','Enter '+n);b.addEventListener('click',()=>sudokuAction(n));$('sudokuNumbers').appendChild(b)}
const sudokuPad=$('sudokuNumbers');sudokuPad.append($('sudokuPencil'),$('sudokuErase'));document.addEventListener('pointerdown',e=>{if(currentPage!=='sudoku'||!sudokuPad.classList.contains('open'))return;if(!sudokuPad.contains(e.target)&&!e.target.closest('.sudoku-cell'))closeSudokuPad()});window.addEventListener('resize',()=>{if(currentPage==='sudoku')closeSudokuPad()})"""
if old_pad not in s:
    raise SystemExit('sudoku number pad source not found')
s=s.replace(old_pad,new_pad,1)
old_pencil="""$('sudokuPencil').addEventListener('click',()=>{pencil=!pencil;$('sudokuPencil').setAttribute('aria-pressed',String(pencil));$('sudokuMessage').textContent=pencil?'Notes mode on.':'Notes mode off.'});"""
new_pencil="""$('sudokuPencil').addEventListener('click',()=>{pencil=!pencil;$('sudokuPencil').setAttribute('aria-pressed',String(pencil));$('sudokuMessage').textContent=pencil?'Notes mode · choose candidates.':'Tap a cell, then choose a number.';if(sudoku.selected!=null)positionSudokuPad(sudoku.selected)});"""
if old_pencil not in s:
    raise SystemExit('pencil listener source not found')
s=s.replace(old_pencil,new_pencil,1)
s=s.replace("Tap an empty cell, then a number.","Tap a cell to choose a number.",1)
p.write_text(s)
print('Sudoku contextual full-screen UI patched')
